INSERT INTO Cakes (Name, Description, BasePrice, PhotoUrl, CategoryId, IsAvailable, Weight, IsCustomizable, Ingredients) VALUES
('Малиновий', 'Торт із ванільного бісквіта з крем-чизом і малиною. У складі також вершки та мигдаль.', 850, '/images/raspberry-cake.jpg', 1, 1, '1.2 кг', 0, 'Ванільний бісквіт,Крем-чиз,Малина,Вершки,Мигдаль'),
('Полуничний', 'Бісквітний торт із вершковим кремом, полуницею та желе. У смаку поєднуються вершкова основа й полуничні ноти. Желе доповнює ягідну частину торта.', 920, '/images/strawberry-cake.jpg', 1, 1, '1.4 кг', 0, 'Бісквіт,Вершковий крем,Полуниця,Желе'),
('Класичний медовик', 'Торт із медових коржів зі сметанним кремом і горіхами. Мед надає коржам характерного аромату, а сметанний крем додає кислинку. Горіхи доповнюють медовий смак.', 780, '/images/honey-cake.jpg', 2, 1, '1.6 кг', 0, 'Медові коржі,Сметанний крем,Горіхи'),
('Медовик з горіхами', 'Медові коржі з карамельним кремом і волоськими горіхами. У смаку поєднуються мед, карамель і горіхові ноти. Варіант для тих, хто обирає торт без ягідної начинки.', 820, '/images/honey-nuts-cake.jpg', 2, 1, '1.5 кг', 0, 'Медові коржі,Карамельний крем,Волоський горіх'),
('Чизкейк Нью-Йорк', 'Чізкейк із крем-сиру та ванілі на пісочній основі. Основний смак — вершково-сирний, із ванільним ароматом. Пісочна основа відрізняється за текстурою від сирної частини; ягід у складі немає.', 950, '/images/new-york-cheesecake.jpg', 3, 1, '1.3 кг', 0, 'Пісочна основа,Крем-чиз,Яйця,Цукор,Ваніль'),
('Полуничний чизкейк', 'Чізкейк на пісочній основі з полуницею та желе. Вершково-сирна частина поєднується з полуничним смаком і ягідною кислинкою. На відміну від бісквітного торта, основу тут становить пісочний шар.', 990, '/images/strawberry-cheesecake.jpg', 3, 1, '1.4 кг', 0, 'Пісочна основа,Крем-чиз,Полуниця,Желе'),
('Шоколадний мус', 'Торт із бісквітною основою, шоколадним мусом і дзеркальною глазур’ю. Основний смак — шоколадний, а мус має повітрянішу текстуру, ніж бісквіт. Глазур утворює гладке покриття поверх торта.', 1050, '/images/chocolate-mousse.jpg', 4, 1, '1.2 кг', 0, 'Шоколадний мус,Дзеркальна глазур,Бісквіт'),
('Фісташковий мус', 'Торт із бісквітною основою, фісташковим мусом і праліне. Фісташка задає основний горіховий смак, який доповнює праліне. Мусова частина відрізняється за текстурою від бісквітної основи.', 1100, '/images/pistachio-mousse.jpg', 4, 1, '1.3 кг', 0, 'Фісташковий мус,Праліне,Бісквіт'),
('Весільний класичний', 'Торт із ванільного бісквіта з масляним кремом, мастикою та білим декором. Основа смаку — ваніль і вершкові ноти крему. Бажаний напис та деталі оформлення можна вказати в коментарі до замовлення.', 2500, '/images/wedding-classic.jpg', 5, 1, '3.0 кг', 0, 'Ванільний бісквіт,Масляний крем,Мастика,Декор'),
('Весільний з декором', 'Бісквітний торт із крем-чизом, ягодами та квітковим оформленням. Крем додає вершково-сирний смак, а ягоди — кислинку. Побажання до квітів і напису вкажіть у коментарі до замовлення.', 3200, '/images/wedding-flower-cake.jpg', 5, 1, '3.5 кг', 0, 'Бісквіт,Крем-чиз,Живі квіти,Ягоди'),
('Дитячий з декором', 'Ванільний бісквіт із масляним кремом, мастикою та цукровим декором у вигляді єдинорога. Основа смаку — ваніль і крем. Ім’я, вік та бажані кольори оформлення вкажіть у коментарі до замовлення.', 950, '/images/unicorn-cake.jpg', 6, 1, '1.8 кг', 0, 'Ванільний бісквіт,Масляний крем,Мастика,Цукровий декор'),
('Дитячий шоколадний', 'Шоколадний бісквіт із масляним кремом і шоколадним декором. Шоколад є і в основі торта, і в оформленні. Побажання до напису та декору можна залишити в коментарі до замовлення.', 880, '/images/kids-chocolate-cake.jpg', 6, 1, '1.6 кг', 0, 'Шоколадний бісквіт,Масляний крем,Шоколадний декор'),
('Тирамісу', 'Тирамісу із савоярді, маскарпоне, кавою та какао. Кава надає десерту характерного аромату, маскарпоне — вершкового смаку, а какао додає гірчинку. Основу десерту становить печиво савоярді, яке поєднується з кремом із маскарпоне.', 870, '/images/tiramisu-cake.jpg', 7, 1, '1.2 кг', 0, 'Савоярді,Маскарпоне,Кава,Какао'),
('Холодний чизкейк', 'Сирний торт без випікання на основі з печива, з вершковим сиром, ягодами та желе. Сирна частина має вершковий смак, а ягоди додають кислинку. Замість бісквіта тут використана основа з печива.', 750, '/images/no-bake-cheesecake.jpg', 7, 1, '1.1 кг', 0, 'Печиво,Вершковий сир,Ягоди,Желе'),
('Фітнес-торт', 'Торт на мигдалевому борошні з кокосовим кремом, стевією та ягодами. У смаку поєднуються мигдаль, кокос і ягідна кислинка. Для підсолодження використовується стевія; у складі є горіхи.', 980, '/images/no-sugar-gluten-cake.png', 8, 1, '1.0 кг', 0, 'Мигдалеве борошно,Стевія,Ягоди,Кокосовий крем'),
('Протеїновий торт', 'Торт із протеїнового бісквіта з йогуртовим кремом і ягодами. Йогуртовий крем і ягоди додають кислинку. Основу становить протеїновий бісквіт, доповнений кремом і ягідною частиною.', 1020, '/images/protein-cake.jpg', 8, 1, '1.1 кг', 0, 'Протеїновий бісквіт,Йогуртовий крем,Ягоди'),
('Індивідуальний дизайн', 'Оберіть бісквіт і крем у формі замовлення. Побажання до напису й декору вкажіть у коментарі.', 900, '/images/your-custom-cake.jpg', 1, 1, NULL, 1, NULL);